"""Finite probability spaces of coin tosses, and changes of measure (Chapter 1).

The n-toss space Omega_n = {H, T}^n is enumerated once and for all, in
lexicographic order with heads first: outcome ``i`` is the binary expansion of
``i`` on n digits, read with 0 = H and 1 = T. In this order the atoms of F_k
(the outcomes that share their first k tosses) are consecutive blocks of
2**(n - k) outcomes.

Conventions used throughout:

* a random variable is a float array with one entry per outcome;
* a probability measure is an array ``prob`` of outcome probabilities;
* a sigma-algebra generated by a partition is an integer array of atom labels,
  one per outcome (two outcomes lie in the same atom iff their labels agree).

Everything is exact enumeration, except the two Gaussian helpers at the end,
which sample and take a ``seed``.
"""
from __future__ import annotations

from math import comb

import numpy as np


# ---------------------------------------------------------------- the space


def toss_space(n: int) -> np.ndarray:
    """All 2**n outcomes of n tosses, as an int array of shape (2**n, n): 1 = heads, 0 = tails.

    Row ``i`` is outcome ``i`` in lexicographic order with heads first, so row 0 is HH...H
    and the last row is TT...T.
    """
    if n < 0:
        raise ValueError("n must be nonnegative")
    idx = np.arange(2**n)[:, None]
    bits = (idx >> np.arange(n - 1, -1, -1)) & 1  # first toss = most significant digit
    return (1 - bits).astype(int)


def outcome_names(heads: np.ndarray) -> list[str]:
    """Outcomes written as words, e.g. ``['HH', 'HT', 'TH', 'TT']`` for n = 2."""
    return ["".join("H" if h else "T" for h in row) for row in np.asarray(heads)]


def heads_count(heads: np.ndarray) -> np.ndarray:
    """The number of heads H_k among the first k tosses, shape (2**n, n + 1), with H_0 = 0."""
    heads = np.asarray(heads)
    zeros = np.zeros((heads.shape[0], 1), dtype=int)
    return np.concatenate([zeros, np.cumsum(heads, axis=1)], axis=1)


def toss_probabilities(heads: np.ndarray, p: float) -> np.ndarray:
    """P(omega) = p^{H_n} q^{n - H_n}: independent tosses, each heads with probability p."""
    if not 0.0 <= p <= 1.0:
        raise ValueError("p must lie in [0, 1]")
    heads = np.asarray(heads)
    h = heads.sum(axis=1)
    n = heads.shape[1]
    return p**h * (1.0 - p) ** (n - h)


def stock_prices(heads: np.ndarray, S0: float, u: float, d: float) -> np.ndarray:
    """Binomial stock S_k = S0 u^{H_k} d^{k - H_k}, shape (2**n, n + 1); column k is S_k."""
    H = heads_count(heads)
    k = np.arange(H.shape[1])
    return S0 * u**H * d ** (k - H)


# ------------------------------------------------------- information

def toss_partition(n: int, k: int) -> np.ndarray:
    """Atom labels of F_k = sigma(first k tosses) on the n-toss space: 2**k blocks of 2**(n-k)."""
    if not 0 <= k <= n:
        raise ValueError("need 0 <= k <= n")
    return np.arange(2**n) >> (n - k)


def partition_of(*variables: np.ndarray, decimals: int = 10) -> np.ndarray:
    """Atom labels of sigma(Y_1, ..., Y_m): the level sets of the vector (Y_1, ..., Y_m).

    Values are rounded to ``decimals`` digits first, so that prices computed along
    different paths (e.g. S_0 u d and S_0 d u) are recognised as equal.
    """
    cols = np.column_stack([np.round(np.asarray(v, dtype=float), decimals) for v in variables])
    _, labels = np.unique(cols, axis=0, return_inverse=True)
    return labels.ravel()


def is_measurable(X: np.ndarray, labels: np.ndarray, decimals: int = 10) -> bool:
    """True iff X is constant on every atom of the partition, i.e. X is sigma(partition)-measurable."""
    X = np.round(np.asarray(X, dtype=float), decimals)
    labels = np.asarray(labels)
    return all(np.unique(X[labels == a]).size == 1 for a in np.unique(labels))


# ------------------------------------------------- expectations

def expectation(X: np.ndarray, prob: np.ndarray) -> float:
    """E[X] = sum over outcomes of X(omega) P(omega)."""
    return float(np.dot(np.asarray(X, dtype=float), prob))


def conditional_expectation(X: np.ndarray, prob: np.ndarray, labels: np.ndarray) -> np.ndarray:
    """E[X | sigma(partition)]: on each atom, the probability-weighted average of X over that atom.

    Returns one value per outcome. On atoms of probability zero, where any value is a
    valid version, the result is set to 0.
    """
    X = np.asarray(X, dtype=float)
    _, inv = np.unique(np.asarray(labels), return_inverse=True)
    inv = inv.ravel()
    mass = np.bincount(inv, weights=prob)
    total = np.bincount(inv, weights=prob * X)
    avg = np.divide(total, mass, out=np.zeros_like(total), where=mass > 0)
    return avg[inv]


def least_squares(X: np.ndarray, features: np.ndarray, prob: np.ndarray) -> np.ndarray:
    """Orthogonal projection of X, in L^2(prob), on the span of the columns of ``features``.

    ``features`` has shape (n_outcomes, m). Returns the fitted values, one per outcome:
    the Z in the span that minimises E[(X - Z)^2].
    """
    F = np.asarray(features, dtype=float)
    if F.ndim == 1:
        F = F[:, None]
    w = np.sqrt(np.asarray(prob, dtype=float))
    coef, *_ = np.linalg.lstsq(F * w[:, None], np.asarray(X, dtype=float) * w, rcond=None)
    return F @ coef


def binomial_forecast(h, x, m: int, p: float, u: float, d: float):
    """g(x) = sum_j C(m, j) p^j q^{m-j} h(x u^j d^{m-j}).

    By the independence lemma, E[h(S_n) | F_k] = g(S_k) with m = n - k. ``h`` must accept arrays.
    """
    x = np.asarray(x, dtype=float)
    return sum(comb(m, j) * p**j * (1 - p) ** (m - j) * h(x * u**j * d ** (m - j))
               for j in range(m + 1))


# ------------------------------------------------ change of measure

def coin_density(heads: np.ndarray, p: float, p_tilde: float) -> np.ndarray:
    """dQ/dP for Q the p_tilde-coin and P the p-coin: (p_tilde/p)^{H_n} (q_tilde/q)^{n - H_n}."""
    if not (0 < p < 1 and 0 < p_tilde < 1):
        raise ValueError("p and p_tilde must lie in (0, 1)")
    heads = np.asarray(heads)
    h = heads.sum(axis=1)
    n = heads.shape[1]
    return (p_tilde / p) ** h * ((1 - p_tilde) / (1 - p)) ** (n - h)


def bayes_conditional_expectation(X, Z, prob, labels) -> np.ndarray:
    """E^Q[X | G] computed under P by Bayes' formula E[Z X | G] / E[Z | G], with dQ/dP = Z.

    Returns 0 on atoms where E[Z | G] = 0, which have Q-probability zero.
    """
    num = conditional_expectation(np.asarray(Z) * np.asarray(X), prob, labels)
    den = conditional_expectation(Z, prob, labels)
    return np.divide(num, den, out=np.zeros_like(num), where=den > 0)


# ------------------------------------------------- the Gaussian shift

def gaussian_shift_density(x, theta: float):
    """Z = exp(theta x - theta^2 / 2): the density dQ/dP that turns N(0, 1) into N(theta, 1)."""
    return np.exp(theta * np.asarray(x, dtype=float) - 0.5 * theta**2)


def gaussian_shift_sample(theta: float, n_samples: int, seed=None):
    """Samples X_i ~ N(0, 1) under P, and their weights Z_i = dQ/dP(X_i). Returns ``(X, Z)``.

    Averages of Z_i h(X_i) estimate E^Q[h(X)] = E[h(X + theta)].
    """
    rng = np.random.default_rng(seed)
    x = rng.standard_normal(n_samples)
    return x, gaussian_shift_density(x, theta)


def effective_sample_size(weights) -> float:
    """(sum w)^2 / sum w^2: roughly, how many equally weighted samples the weighted ones are worth."""
    w = np.asarray(weights, dtype=float)
    return float(w.sum() ** 2 / np.sum(w**2))
